import math

def get_smallest_divisor(n):
    """Finds the smallest divisor of n greater than 1."""
    if n < 2:
        return None
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return i
    return n # n is prime

def simulate_worst_case(F, S, max_turns=50):
    X = S

    if X == F:
        return f"Success (S=F)"

    if X == 1:
        return "Failure (Cannot move from 1)"

    for turn in range(max_turns):
        if X == F:
            return f"Success in {turn} turns"

        # 1. Player's Move (Greedy: Minimize towards F, or grow if forced)

        D = get_smallest_divisor(X)

        if D == X: # X is prime
            X_prime = 2 * X
        elif D is None: # Should not happen if X >= 2
            return "Failure (Internal Error)"
        else: # X is composite
            X_prime = D

        # Safety check for X_prime = 1, although unlikely if S >= 2
        if X_prime <= 1:
            return "Failure (Stuck or moved to 1)"

        # 2. Organizer's Worst Case Move

        next_states = [X_prime + 1, X_prime - 1]

        # Filter out states that hit F immediately, unless both do.
        non_winning_states = [s for s in next_states if s != F]

        if not non_winning_states:
            # Both paths lead to F. Guaranteed win this turn.
            return f"Success in {turn + 1} turns (Forced win)"

        # Choose the state furthest from F among non-winning states
        best_next_state = None
        max_distance = -1

        for state in non_winning_states:
            distance = abs(state - F)
            if distance > max_distance:
                max_distance = distance
                best_next_state = state
            elif distance == max_distance:
                # Tie-breaker: if distances are equal, the organizer chooses the state
                # that maximizes the number of future moves needed (e.g., choose larger number if F is small, 
                # or more complex heuristic). For simplicity, we pick the larger one.
                if best_next_state is None or state > best_next_state:
                    best_next_state = state

        X = best_next_state

    return "Failure after 50 turns"

# --- Sweep Tests for F=2 through F=10 ---
S_test = 1000
results = {}
for F in range(2, 11):
    result = simulate_worst_case(F, S_test)
    results[F] = result

for F, result in results.items():
    print(f"F={F}: {result}")

